// Core server-side damage-application routine. Validates the attacker can hit the victim (UNITS_CheckIfCanAttackTarget, town/killable rules) then optionally applies defensive reduction, dispatches hit/got-hit unit events, clamps physical damage to current HP, runs life/mana leech, healing, then subtracts total damage from the victim's hitpoints (clamping the sub-256 remainder to 0). Also applies drain (mana/stamina) and status effects: stun, cold, freeze, poison, burning. Sets wResultFlags death bit (2) when HP reaches 0, otherwise schedules HP-regen events for monsters and clears Assassin charge-up states; dispatches death events on kill. Mutates pDamage and victim stats in place.
// 1.14d: 0057c6c0
void __fastcall DAMAGE_ApplyDamageToUnit(SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pVictim, int32_t bApplyDefenseReduction, D2DamageStrc * pDamage) {
    bool bIsInTown;
    D2RoomStrc* pRoom;
    D2MonStatsTxt* pMonStats;
    int32_t nNewHpCalc;
    int nDamageOrHp;
    uint32_t eEventType;
    eD2UnitType eVictimType;
    D2UnitStrc* pUnit_00;
    pUnit_00 = pVictim;
    uint32_t bCanAttack;
    bCanAttack = D2Game::UNIT::SUnit::UNITS_CheckIfCanAttackTarget(pGame, pUnit, pVictim);
    if (!bCanAttack && !(pDamage->dwHitFlags & 0x1000U) || (pRoom = D2Common::Units::UNITS_GetRoom(pVictim) , !pRoom)) {
      pDamage->wResultFlags &= 0xfffc;
      return;
    }

    pRoom = D2Common::Units::UNITS_GetRoom(pVictim);
    BOOL bIsInTownOrKillable;
    bIsInTownOrKillable = D2Common::DUNGEON::Dungeon::DRLGROOM_IsRoomInTown(pRoom);
    if (bIsInTownOrKillable && (!pUnit || pUnit->eUnitType != UNIT_MONSTER || (pMonStats = D2Common::DATATBLS::MonsterTbls::TXT_MonStats_GetLine(pUnit->nClassId) , !pMonStats || !(pMonStats->field_0xd & (uint8_t)Fog::BitBuffer::gadwBitMasks[2])))) {
      pDamage->wResultFlags &= 0xfffd;
      return;
    }
    if (!pUnit) {
      pVictim = (D2UnitStrc*)0x6;
    } else {
      pVictim = (D2UnitStrc*)pUnit->eUnitType;
    }
    if (!pUnit_00) {
      eVictimType = UNIT_COUNT;
    } else {
      eVictimType = pUnit_00->eUnitType;
      if (eVictimType == UNIT_MONSTER) {
        bIsInTownOrKillable = D2Common::DATATBLS::MonsterTbls::TXT_MonStats_GetFlagsByBitOffset(pUnit_00->nClassId, killable);
        if (!bIsInTownOrKillable) {
          return;
        }
      }
    }

    bIsInTownOrKillable = D2Game::UNIT::SUnit::CheckForModeZeroDeath(pUnit_00);
    if (bIsInTownOrKillable) {
      return;
    }

    D2Common::Units::StoreLastAttacker(pUnit_00, pUnit);
    if (bApplyDefenseReduction) {
      D2Game::UNIT::SUnitDmg::DAMAGE_ApplyDefensiveReduction(pGame, pUnit, pUnit_00, pDamage);
    }
    if (!(pDamage->wResultFlags & 0x20U) && pDamage->wResultFlags & 1U) {
      if (!bApplyDefenseReduction) {
        D2Game::UNIT::SUnitEvent::UNITEVENT_DispatchEventsByType(pGame, 5, pUnit, pUnit_00, pDamage);
        eEventType = 1;
      } else {
        if (!(pDamage->dwHitFlags & 0x20U)) {
          goto clamp_and_apply_damage;
        }
        if (-1 < (char)pDamage->dwHitFlags) {
          D2Game::UNIT::SUnitEvent::UNITEVENT_DispatchEventsByType(pGame, 6, pUnit, pUnit_00, pDamage);
        }

        eEventType = 2;
      }

      D2Game::UNIT::SUnitEvent::UNITEVENT_DispatchEventsByType(pGame, eEventType, pUnit_00, pUnit, pDamage);
    }

    clamp_and_apply_damage:
    nDamageOrHp = pDamage->dwPhysDamage;
    int32_t nCurrentHp = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit_00, UNITSTAT_hitpoints, 0);
    if (nCurrentHp <= nDamageOrHp) {
      nDamageOrHp = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit_00, UNITSTAT_hitpoints, 0);
    }

    pDamage->dwPhysDamage = nDamageOrHp;
    D2Game::UNIT::SUnitDmg::DAMAGE_ApplyLifeAndManaLeech(pGame, pUnit_00, pUnit, pDamage);
    if (pVictim == (D2UnitStrc*)0x1 && pDamage->wResultFlags & 1) {
      D2Game::Monsters::MONSTER_DispatchUModOnAttack(pGame, pUnit);
    }

    D2Game::UNIT::SUnitDmg::DAMAGE_ApplyHealingToUnit(pDamage->dwAbsLife, pUnit_00);
    nDamageOrHp = pDamage->dwDmgTotal;
    if (0 < nDamageOrHp) {
      int nPhysDamage;
      nPhysDamage = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit_00, UNITSTAT_hitpoints, 0);
      nNewHpCalc = nPhysDamage - nDamageOrHp;
      if (nNewHpCalc < 0x100) {
        nNewHpCalc = 0;
      }

      D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit_00, UNITSTAT_hitpoints, nNewHpCalc, 0);
    }

    D2Game::UNIT::SUnitDmg::DAMAGE_DrainManaFromUnit(pDamage->dwManaLeech, pUnit_00);
    D2Game::UNIT::SUnitDmg::DAMAGE_DrainStaminaFromUnit(pDamage->dwStamLeech, pUnit_00);
    D2Game::UNIT::SUnitDmg::DAMAGE_ApplyStun(pUnit, pDamage->dwStunLen, pUnit_00);
    D2Game::UNIT::SUnitDmg::DAMAGE_ApplyCold(pUnit, pDamage->dwColdLength, pUnit_00);
    D2Game::UNIT::SUnitDmg::DAMAGE_ApplyFreeze(pUnit, pDamage->dwFrzLength, pUnit_00);
    D2Game::UNIT::SUnitDmg::DAMAGE_ApplyPoison(pUnit, pDamage->dwPoisDamage, pDamage->dwPoisLength, pUnit_00);
    D2Game::UNIT::SUnitDmg::DAMAGE_ApplyBurning(pUnit, pDamage->dwBurnDmg, pDamage->dwBurnLen, pUnit_00);
    int32_t nNewHp = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit_00, UNITSTAT_hitpoints, 0);
    if (nNewHp < 1) {
      pDamage->wResultFlags |= 2;
    } else {
      pDamage->wResultFlags &= 0xfffd;
      if (pDamage->dwDmgTotal && eVictimType == UNIT_MONSTER) {
        nDamageOrHp = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit_00, UNITSTAT_hpregen, 0);
        if (nDamageOrHp) {
          D2Game::GAME::Event::EVENT_RemoveUnitTimersByType(pGame, pUnit_00, UNITEVENTCALLBACK_STATREGEN, 0);
          D2Game::GAME::Event::SetEvent(pGame, pUnit_00, 3, pGame->dwGameFrame + 1, 0, 0);
        }

        D2Game::SKILLS::SkillAss::SKILLASS_ClearAllChargeUpStates(pUnit_00);
      }
    }
    if (!(!(pDamage->wResultFlags & 0x20U) && pDamage->wResultFlags & 2U)) {
      return;
    }

    D2Game::UNIT::SUnitEvent::UNITEVENT_DispatchEventsByType(pGame, 10, pUnit_00, pUnit, pDamage);
    D2Game::UNIT::SUnitEvent::UNITEVENT_DispatchEventsByType(pGame, 9, pUnit, pUnit_00, pDamage);
}

