  uD2UnitMode eAnimMode;
  eD2UnitType eUnitType;
  D2UnitStrc *pDefenderSaved;
  D2MonStatsTxt *pMonStats;

  pDefenderSaved = pDefender;
  if ((pDmgStrc->dwLifeLeech == 0) && (pDmgStrc->dwManaLeech == 0)) {
    return;
  }
  if ((pDefender == (D2UnitStrc *)0x0) || (pDefender->eUnitType != UNIT_MONSTER)) {
    pDefender = (D2UnitStrc *)0x64;
  }
  else {
    if ((pDefender->pUnitData).pUnitDataMonster == (D2UnitDataMonsterStrc *)0x0) {
      return;
    }
    pMonStats = ((pDefender->pUnitData).pUnitDataMonster)->pMonStatsTxt;
    if (pMonStats == (D2MonStatsTxt *)0x0) {
      return;
    }
    pDefender = (D2UnitStrc *)(uint)pMonStats->aDrain[pGame->nDifficulty];
    if (pDefender == (D2UnitStrc *)0x0) {
      return;
    }
  }
  pDmgStrc->dwLifeLeech = pDmgStrc->dwLifeLeech << 6;
  pDmgStrc->dwManaLeech = pDmgStrc->dwManaLeech << 6;
  if (pAttacker == (D2UnitStrc *)0x0) {
    eUnitType = UNIT_COUNT;
apply_monster_drain:
    if (pAttacker == (D2UnitStrc *)0x0) {
      nManaStat = -1;
      eAnimMode.ePlayerMode = Death;
    }
    else {
      nManaStat = pAttacker->nClassId;
      eAnimMode = pAttacker->eAnimMode;
    }
    D2Common::Skills::Skills::SKILLS_GetStateTransformGfx
              (pAttacker,&eUnitType,&nManaStat,(int *)&eAnimMode.ePlayerMode,".\\UNIT\\SUnitDmg.cpp"
               ,0x64c);
    if (eUnitType != UNIT_PLAYER) {
      nManaStat = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pDefenderSaved,UNITSTAT_mana,0);
      eAnimMode.ePlayerMode =
           D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pDefenderSaved,UNITSTAT_stamina,0);
      nLifeLeechAmt = (int)(pDmgStrc->dwLifeLeech + (pDmgStrc->dwLifeLeech >> 0x1f & 0x3fU)) >> 6;
      nMaxHp = (int)(pDmgStrc->dwManaLeech + (pDmgStrc->dwManaLeech >> 0x1f & 0x3fU)) >> 6;
      pDmgStrc->dwLifeLeech = nLifeLeechAmt;
      pDmgStrc->dwManaLeech = nMaxHp;
      if (pDmgStrc->dwPhysDamage <= nLifeLeechAmt) {
        nLifeLeechAmt = pDmgStrc->dwPhysDamage;
      }
      if (nManaStat <= nMaxHp) {
        nMaxHp = nManaStat;
      }
      nStamLeechAmt = eAnimMode.ePlayerMode;
      if (pDmgStrc->dwStamLeech < (int)eAnimMode.ePlayerMode) {
        nStamLeechAmt = pDmgStrc->dwStamLeech;
      }
