    }
  }
  else if (pAttacker->eUnitType == UNIT_PLAYER) {
    pGameFromUnit = D2Game::UNIT::SUnit::GetGamePointer(pAttacker);
    pDiffLevels = D2Common::DATATBLS::DataTbls::GetDifficultyLevels
                            ((uint)pGameFromUnit->nDifficulty);
    if (pDiffLevels->LifeStealDivisor != 0) {
      pDmgStrc->dwLifeLeech = pDmgStrc->dwLifeLeech / pDiffLevels->LifeStealDivisor;
    }
    if (pDiffLevels->ManaStealDivisor != 0) {
      pDmgStrc->dwManaLeech = pDmgStrc->dwManaLeech / pDiffLevels->ManaStealDivisor;
    }
  }
  else if ((pAttacker->eUnitType != UNIT_MONSTER) ||
          (nMercType = D2Common::Monsters::MONSTERS::MONSTER_GetMercType(pAttacker), nMercType == 0)
          ) {
    eUnitType = pAttacker->eUnitType;
    goto apply_monster_drain;
  }
  nManaStat = pDmgStrc->dwPhysDamage;
  eUnitType = UNIT_PLAYER;
  if (0 < nManaStat) {
    if (pDmgStrc->dwManaLeech != 0) {
      nLeechAmount = D2Common::DATATBLS::DataTbls::D2ApplyPercent
                               (nManaStat,pDmgStrc->dwManaLeech,100);
      if (pDefender != (D2UnitStrc *)0x64) {
        nLeechAmount = D2Common::DATATBLS::DataTbls::D2ApplyPercent
                                 (nLeechAmount,(int32_t)pDefender,100);
      }
      D2Game::UNIT::SUnitDmg::DAMAGE_ApplyManaToUnit
                ((int)(nLeechAmount + (nLeechAmount >> 0x1f & 0x3fU)) >> 6,pAttacker);
      eUnitType = UNIT_MONSTER;
    }
    if (pDmgStrc->dwLifeLeech == 0) {
      if (eUnitType == UNIT_PLAYER) {
        return;
      }
    }
    else {
      nMaxHp = D2Common::DATATBLS::DataTbls::D2ApplyPercent(nManaStat,pDmgStrc->dwLifeLeech,100);
      if (pDefender != (D2UnitStrc *)0x64) {
        nMaxHp = D2Common::DATATBLS::DataTbls::D2ApplyPercent(nMaxHp,(int32_t)pDefender,100);
      }
      D2Game::UNIT::SUnitDmg::DAMAGE_ApplyHealingToUnit
                ((int)(nMaxHp + (nMaxHp >> 0x1f & 0x3fU)) >> 6,pAttacker);
      if (eUnitType == UNIT_PLAYER) {
set_leech_overlay:
        D2Common::Units::Units::SetOverlay(pAttacker,0x97,0);
        return;
      }
      uMercType = D2Common::Seed::UNIT_GetModuloFromSeed(&pAttacker->sSeed,2);
      if (uMercType == 0) {
        D2Common::Units::Units::SetOverlay(pAttacker,0x97,0);
        return;
      }
    }
    D2Common::Units::Units::SetOverlay(pAttacker,0x98,0);
  }
  return;
}

